ruleToc.chapterList:
@js:(function(){
var out=[];
var groupRe=/<div[^>]*class="[^"]*detail-selector-item[^"]*"[^>]*onclick="[^"]*titleSelect\([^)]*,[^)]*,\s*['"]([^'"]+)['"]\)[^"]*"[^>]*>([\s\S]*?)<\/div>/g;
var gm;
while((gm=groupRe.exec(result))){
  var listId=gm[1];
  var idRe=new RegExp('<div[^>]*id="'+listId+'"[^>]*>[\s\S]*?(<a[^>]*class="[^"]*chapteritem[^"]*"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>)','g');
  var m;
  while((m=idRe.exec(result))){
    var t=m[3].replace(/<[^>]+>/g,'').trim()||m[2];
    var u=m[2];if(u.indexOf('http')<0)u='https://www.manhuaren.com'+u;
    out.push({name:t,url:u});
  }
}
if(out.length===0){
  var fallbackRe=/<a[^>]*class="[^"]*chapteritem[^"]*"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
  var m2;
  while((m2=fallbackRe.exec(result))){
    var t2=m2[2].replace(/<[^>]+>/g,'').trim()||m2[1];
    var u2=m2[1];if(u2.indexOf('http')<0)u2='https://www.manhuaren.com'+u2;
    out.push({name:t2,url:u2});
  }
}
return out;})()

ruleContent.content:
@js:(function(){
var i=result.indexOf("eval(function(p,a,c,k,e,d)");
if(i<0)return '';
var script=result.substring(i);
var pStart=script.indexOf("}('")+3;
var boundary=script.substring(pStart).match(/',(\d+),(\d+),'/);
if(!boundary)return '';
var bi=boundary.index+pStart;
var rawP=script.substring(pStart,bi);
var a=parseInt(boundary[1],10);
var c=parseInt(boundary[2],10);
var kStart=bi+boundary[0].length;
var kEnd=script.indexOf("'.split",kStart);
var rawK=script.substring(kStart,kEnd);
var dict=rawK.split('|');
var e=function(c){return(c<a?'':e(parseInt(c/a)))+((c=c%a)>35?String.fromCharCode(c+29):c.toString(36));};
var d={};
var cc=c;
while(cc--)d[e(cc)]=dict[cc]||e(cc);
var dec=rawP.replace(/\b\w+\b/g,function(w){return d[w]||w;});
var am=dec.match(/\[([\s\S]*?)\]/);
if(!am)return '';
var items=am[1].split(',').map(function(it){return it.trim().replace(/^\?['"]|\?['"]$/g,'');});
var out=[];
for(var j=0;j<items.length;j++){if(items[j].indexOf('http')===0)out.push('<img src="'+items[j]+'">');}
return out.join('\n');})()

